-- ============================================================
-- SEED EXT 4: Módulo 15 — Gerund & Infinitive (ex 156-220)
-- Novos tópicos: gerundio vs infinitivo com mudança de sentido,
-- nominalizações com gerúndio, infinitivo como sujeito formal,
-- estruturas complexas em TOEFL academic writing
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'gerund-infinitive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo gerund-infinitive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Verbos que mudam de sentido (remember/forget/stop/try/regret/mean)
  (cid,41,156,'multiple_choice','What is the difference: "He stopped to check the data" vs "He stopped checking the data"?','"Stopped to check" = he paused in order to check. "Stopped checking" = he ceased the activity of checking.','["They are identical","''Stopped to check'' = he paused in order to check. ''Stopped checking'' = he ceased the activity of checking.","''Stopped to check'' is wrong grammar","''Stopped checking'' means he forgot to check"]','Stop + to inf = purpose (stopped in order to do). Stop + gerund = ceased doing.','hard'),
  (cid,41,157,'multiple_choice','What is the difference: "Remember to submit the report" vs "I remember submitting the report"?','"Remember to submit" = obligation to do in the future. "Remember submitting" = recall a past action.','["They are identical","''Remember to submit'' = obligation to do in the future. ''Remember submitting'' = recall a past action.","Gerund always refers to the present","Infinitive always refers to the future"]','Remember + to inf = future/obligation. Remember + gerund = memory of past.','hard'),
  (cid,41,158,'gap_fill','I regret _____ (inform) you that your application has not been successful.','to inform',NULL,'"Regret + to inf" = formal present: I am sorry to tell you this now.','hard'),
  (cid,41,159,'gap_fill','She regrets _____ (not/pursue) a postgraduate degree while she had the opportunity.','not pursuing',NULL,'"Regret + gerund" = past decision she now wishes were different.','hard'),
  (cid,41,160,'multiple_choice','Which pair CORRECTLY distinguishes gerund and infinitive meanings?','"Try adding more data" (experiment) vs "Try to find the correlation" (attempt a difficult goal).','["''Try to add'' (experiment) vs ''try adding'' (difficult attempt)","''Try adding more data'' (experiment) vs ''try to find the correlation'' (attempt a difficult goal).","Both meanings are the same","Try always takes gerund in academic writing"]','Try + gerund = experiment (test as a solution). Try + to inf = attempt (something difficult).','hard'),
  (cid,41,161,'gap_fill','The method _____ (mean) _____ (collect) samples from three different sites, which _____ (mean) _____ (travel) to remote locations.','means / collecting / meant / travelling',NULL,'"Mean + gerund" = involve/entail (not mean + to inf = intend).','hard'),

  -- BLOCK 42: Gerúndio após preposições e em nominalizações
  (cid,42,162,'gap_fill','The researchers are committed to _____ (minimize) the risk of measurement error.','minimizing',NULL,'"Committed to + gerund": "to" here is a preposition, not infinitive marker.','medium'),
  (cid,42,163,'gap_fill','The policy resulted in _____ (reduce) carbon emissions by 15% over five years.','reducing',NULL,'"Result in + gerund" for outcome.','medium'),
  (cid,42,164,'multiple_choice','Which sentence correctly uses a gerund after a PREPOSITION?','The committee is responsible for reviewing all submitted applications.','["The committee is responsible to review all submitted applications.","The committee is responsible for reviewing all submitted applications.","The committee is responsible for to review all submitted applications.","The committee is responsible reviewing all submitted applications."]','"Responsible for + gerund": preposition "for" → gerund, not infinitive.','easy'),
  (cid,42,165,'gap_fill','In addition to _____ (analyze) the quantitative data, the researchers _____ (also/conduct) semi-structured interviews.','analyzing / also conducted',NULL,'"In addition to + gerund" (prepositional phrase).','medium'),
  (cid,42,166,'gap_fill','The success of the program _____ (depend on) _____ (secure) long-term funding from multiple sources.','depends on / securing',NULL,'"Depend on + gerund" for the condition.','medium'),
  (cid,42,167,'multiple_choice','Which sentence uses a GERUND AS SUBJECT correctly and formally?','Designing effective public health campaigns requires understanding both behavioral science and cultural context.','["To design effective public health campaigns requires understanding both behavioral science and cultural context (both correct).","Designing effective public health campaigns requires understanding both behavioral science and cultural context.","Design effective public health campaigns requires understanding cultural context.","Designing effective public health campaigns require understanding cultural context (subject-verb agreement error: gerund subject → singular → requires)."]','Gerund as subject = singular verb: "Designing... requires."','hard'),

  -- BLOCK 43: Infinitivo formal (sujeito, objeto, complemento)
  (cid,43,168,'multiple_choice','In formal academic writing, which subject construction is often preferred over gerund as subject?','It + be + adjective + to-infinitive.','["Active voice is always preferred","It + be + adjective + to-infinitive.","Passive voice with gerund","Present participle as subject"]','"It is essential to understand..." = formal academic. "Understanding is essential" = both correct, different focus.','medium'),
  (cid,43,169,'gap_fill','It _____ (essential) to _____ (distinguish) between correlation and causation when _____ (interpret) research findings.','is essential / distinguish / interpreting',NULL,'"It is essential + to + base verb" + "when + gerund" for simultaneous action.','medium'),
  (cid,43,170,'gap_fill','The aim of this study _____ (be) _____ (examine) the relationship between social capital and academic attainment.','is / to examine',NULL,'"The aim... is + to + base verb" = infinitive as complement of aim.','easy'),
  (cid,43,171,'gap_fill','Policymakers need _____ (understand) that _____ (implement) evidence-based policy _____ (require) _____ (acknowledge) uncertainty.','to understand / implementing / requires / acknowledging',NULL,'Need + to inf + that + gerund subject + verb + gerund.','hard'),
  (cid,43,172,'multiple_choice','Which sentence uses "appear + infinitive" CORRECTLY in academic style?','The relationship appears to be bidirectional, with each variable influencing the other.','["The relationship appears being bidirectional.","The relationship appears to be bidirectional, with each variable influencing the other.","The relationship appears that it is bidirectional.","The relationship is appearing to be bidirectional (PC wrong with stative appear)."]','"Appear + to + be" = formal academic reporting of observation. Stative → no PC.','medium'),

  -- BLOCK 44: Complexas estruturas combinadas
  (cid,44,173,'gap_fill','The committee agreed _____ (delay) the vote in order to allow more time for _____ (deliberate).','to delay / deliberating',NULL,'"Agree + to inf" + "in order to + base" + "for + gerund."','hard'),
  (cid,44,174,'gap_fill','It is worth _____ (note) that the results of _____ (implement) this policy _____ (not/know/passive) in advance.','noting / implementing / were not known',NULL,'"Worth + gerund" + "of + gerund" + PS passive for past uncertainty.','hard'),
  (cid,44,175,'multiple_choice','Which sentence correctly uses BOTH gerund and infinitive?','The government tends to avoid making commitments without first consulting its advisers.','["The government tends avoiding to make commitments.","The government tends to avoid making commitments without first consulting its advisers.","The government tends to avoid to make commitments without consulting.","The government avoids tending making commitments."]','"Tend + to inf" + "avoid + gerund" + "without + gerund" = correct chain.','hard'),
  (cid,44,176,'gap_fill','Researchers suggest _____ (increase) the sample size _____ (ensure) adequate statistical power.','increasing / to ensure',NULL,'"Suggest + gerund" + infinitive of purpose.','medium'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,177,'multiple_choice','[TOEFL Reading] "The study demonstrated the importance of controlling for confounding variables." In this sentence, "controlling" is:','A gerund functioning as the object of the preposition "of."','["An adjective modifying ''variables''","A gerund functioning as the object of the preposition ''of.''","A present participle in an active RC","A reduced passive clause"]','"Of + controlling" = gerund as object of preposition.','medium'),
  (cid,45,178,'gap_fill','[TOEFL Reading] "Researchers were able _____ (identify) three distinct subpopulations by _____ (apply) cluster analysis to the dataset." Best forms?','to identify / applying',NULL,'"Able + to inf" + "by + gerund" = method clause.','medium'),
  (cid,45,179,'multiple_choice','[TOEFL Reading] "It remains crucial to examine whether early intervention programs prevent long-term educational disadvantage." The infinitive "to examine" here:','Acts as the notional subject of the sentence (formal it-subject construction).','["Is an object of ''remains''","Acts as the notional subject of the sentence (formal it-subject construction).","Describes a past action","Modifies ''early intervention''"]','"It remains crucial to [do X]" = it = anticipatory subject; "to examine" = real subject.','hard'),
  (cid,45,180,'gap_fill','[TOEFL Reading] "The authors advocate _____ (revise) the regulatory framework rather than _____ (attempt) to enforce rules _____ (design) for a different technological era." Best forms?','revising / attempting / designed',NULL,'"Advocate + gerund" + "rather than + gerund" + reduced passive RC.','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,181,'production','[TOEFL Speaking — 45s] The reading discusses the challenges of implementing a new energy policy. The lecture adds that decision-makers tend to avoid making long-term commitments. Summarize using gerunds and infinitives.','',NULL,'The reading describes the challenges that governments face in implementing comprehensive energy transition policies. It points out that making the infrastructure investments required for a full transition to renewable energy requires committing large amounts of public capital over multi-decade timeframes. The lecture complicates this picture by pointing out that political systems are structurally inclined to avoid making commitments that extend beyond electoral cycles. The professor notes that decision-makers tend to prioritize appearing responsive to short-term economic pressures rather than acknowledging the long-term consequences of delaying action. This creates a fundamental tension: the changes needed require deciding to act now for benefits that will materialize only decades later, while the costs of acting are immediate and politically visible.','hard'),
  (cid,46,182,'production','[TOEFL Speaking — 45s] Discuss whether it is better to specialize early in a career or to pursue a broad range of experiences. Use gerunds and infinitives throughout.','',NULL,'The question of whether to specialize early or to pursue broad experience touches on a fundamental tension in career development theory. Specializing early offers the advantage of accumulating deep expertise quickly, enabling a person to become genuinely excellent at a specific skill or domain relatively fast. Being an acknowledged expert in a narrow area can open doors that remain closed to generalists. However, developing a broad base of experience before specializing allows for recognizing which domains are most engaging and where one''s comparative strengths actually lie — a form of informed self-knowledge that is difficult to acquire without trying multiple things. Most career researchers suggest delaying premature specialization until a person has had sufficient experience to make the choice informedly. The cost of choosing to specialize in the wrong area — discovering too late that it neither suits your abilities nor engages your interests — can be considerable in terms of both time and opportunity cost.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,183,'production','[TOEFL Writing — 150 words] Write a body paragraph on the value of international education exchange. Use gerunds (×4) and infinitives (×4).','',NULL,'Participating in international education exchange programs offers students opportunities that domestic education alone cannot replicate. Learning alongside peers from diverse cultural backgrounds develops the intercultural competence that employers in globally integrated organizations increasingly regard as essential. Living abroad also forces students to adapt to institutional systems, social norms, and communication styles that differ markedly from those they have internalized at home — a process that researchers associate with enhanced cognitive flexibility and empathy. It is difficult to overestimate the value of being required to navigate unfamiliar systems without the usual support networks: the experience builds problem-solving capacity and self-reliance. Universities have been right to emphasize the importance of internationalizing their curricula, but classroom exposure to global perspectives is not equivalent to actually spending a year immersed in another academic culture. To achieve the full benefits of international experience, students need to engage with the host culture beyond the campus boundaries.','hard'),
  (cid,47,184,'production','[TOEFL Writing — Error Correction] Fix gerund/infinitive errors: "She forgot submitting the form (meant she didn''t do it). They stopped to work for the day. I regret to have missed your lecture. It is crucial understanding the data before analyzing it. The study aims at examine the relationship."','',NULL,'forgot submitting → forgot to submit (forget + to inf = obligation not done in the future/present; forget + gerund = no memory of past action); stopped to work = this actually could be correct (paused in order to work) or stopped working if she ceased; regret to have missed → regret missing (regret + gerund for past event she is sorry about; regret + to inf is for formal present: ''I regret to inform you...''); It is crucial understanding → It is crucial to understand (crucial + to inf, not gerund); aims at examine → aims to examine OR aims at examining (aim + to inf = standard; aim at + gerund also possible).','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,185,'production','[TOEFL Writing — 200 words] Write a body paragraph on the challenges of measuring well-being. Use: gerund as subject (×2), infinitive as complement (×2), gerund after preposition (×3), and complex verb + gerund/infinitive chains.','',NULL,'Measuring human well-being presents methodological challenges that economists and psychologists have struggled to resolve for decades. Reducing the complex experience of living a good life to a single quantitative index involves making choices that are inescapably normative: deciding which dimensions of experience matter most and how to weight them relative to each other. GDP per capita remains the most widely used proxy for well-being, despite being designed to measure market output rather than welfare. Its persistence is partly a consequence of being administratively convenient — governments are already committed to collecting the necessary data — and partly a consequence of policymakers'' resistance to replacing a familiar metric with something more complex and contested. Alternatives to income-based measurement, such as the Human Development Index and the OECD Better Life Index, attempt to incorporate health, education, and subjective life satisfaction into a composite measure. However, comparing these across cultures requires assuming that respondents attach similar meanings to questions about happiness and life satisfaction — an assumption that cross-cultural psychology has good reasons to question. Developing better measures of well-being means confronting fundamental philosophical disagreements about what a good life consists in.','hard'),
  (cid,48,186,'production','[TOEFL Speaking — 60s] Describe the ideal approach to learning a second language. Use gerunds and infinitives to describe processes, goals, and methods.','',NULL,'Learning a second language to a high level of proficiency is one of the most cognitively demanding but also most rewarding educational projects an adult can undertake. The key to succeeding at this task lies in combining structured formal study with extensive and varied exposure to the language in use. Memorizing grammar rules and completing structured exercises builds the explicit linguistic knowledge that forms a foundation, but transforming that knowledge into fluent communicative competence requires being willing to use the language imperfectly in real communication situations before one feels ready to do so. Research on second language acquisition consistently suggests that the most effective learners are those committed to seeking out authentic input — reading widely, listening to native speakers, and speaking with tolerance for mistakes. It is particularly useful to try noticing how specific features of the language — tense, aspect, modality — work in authentic texts, rather than relying only on textbook examples. Using the language for purposes you genuinely care about — reading about topics you find interesting, writing about things that matter to you — is what distinguishes learners who plateau from those who keep improving.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
